/**
 * Phase H — Quranic Vocabulary / Gharib Al-Quran (live QAC data)
 *
 * Full vocabulary lookup backed by the Quranic Arabic Corpus (QAC).
 * Shows root, morphological pattern, POS, English gloss, Arabic meaning,
 * and source attribution for every looked-up word.
 *
 * Per policy: word meanings must NEVER be generated by AI alone.
 */
import { useState } from 'react';
import { Link } from 'react-router-dom';
import {
  Search,
  BookOpen,
  AlertCircle,
  Clock,
  BookMarked,
  Globe,
  FlaskConical,
  Info,
  ArrowRight,
  CheckCircle,
} from 'lucide-react';
import { useLanguageStore } from '../../stores/languageStore';
import { t } from '../../i18n/translations';
import { vocabularyApi, VocabularyResponse } from '../../lib/api';
import clsx from 'clsx';

