const EXAMPLE_WORDS = ['صمد', 'رحمة', 'تقوى', 'نور', 'صبر', 'حكمة', 'إخلاص', 'توكّل'];

// ---------------------------------------------------------------------------
// Main page
// ---------------------------------------------------------------------------

export function VocabularyPage() {
  const { language } = useLanguageStore();
  const isRtl = language === 'ar';

  const [query, setQuery] = useState('');
  const [result, setResult] = useState<VocabularyResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    const word = query.trim();
    if (!word) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const res = await vocabularyApi.lookup(word);
      setResult(res.data);
    } catch {
      setError(language === 'ar' ? 'حدث خطأ. حاول مجدداً.' : 'An error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-8" dir={isRtl ? 'rtl' : 'ltr'}>

      {/* Header */}
      <div className="mb-6 text-center">
        <div className="flex items-center justify-center gap-3 mb-4">
          <div className="p-3 bg-teal-50 rounded-xl border border-teal-100">
            <BookOpen className="w-8 h-8 text-teal-600" />
          </div>
        </div>
        <h1 className={clsx('text-3xl font-bold text-gray-900 mb-2', isRtl && 'font-arabic')}>
          {t('vocab_page_title', language)}
        </h1>
        <p className={clsx('text-gray-500 max-w-xl mx-auto text-base', isRtl && 'font-arabic')}>
          {t('vocab_page_subtitle', language)}
        </p>
      </div>

      {/* About Gharib Al-Quran */}
      <div className={clsx(
        'rounded-xl border border-teal-100 bg-teal-50/60 px-5 py-4 mb-6 flex gap-3',
        isRtl && 'flex-row-reverse'
      )}>
        <Info className="w-5 h-5 text-teal-600 shrink-0 mt-0.5" />
        <p className={clsx('text-sm text-teal-800 leading-relaxed', isRtl && 'text-right font-arabic')}
           dir={isRtl ? 'rtl' : 'ltr'}>
          {t('vocab_about_gharib', language)}
        </p>
      </div>

      {/* Search form */}
      <form onSubmit={handleSearch} className="mb-4">
        <div className="flex gap-3">
          <div className="relative flex-1">
            <Search className={clsx(
              'absolute top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 pointer-events-none',
              isRtl ? 'right-3' : 'left-3'
            )} />
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder={t('vocab_search_placeholder', language)}
              className={clsx(
                'w-full border border-gray-300 rounded-lg py-3 text-base shadow-sm',
                'focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-teal-500',
                isRtl ? 'pr-10 pl-4 text-right font-arabic' : 'pl-10 pr-4'
              )}
              dir={isRtl ? 'rtl' : 'ltr'}
            />
          </div>
          <button
            type="submit"
            disabled={loading || !query.trim()}
            className={clsx(
              'px-6 py-3 bg-teal-600 text-white rounded-lg font-medium shadow-sm',
              'hover:bg-teal-700 active:bg-teal-800 transition-colors',
              'disabled:opacity-50 disabled:cursor-not-allowed',
              isRtl && 'font-arabic'
            )}
          >
            {loading ? '...' : t('vocab_search_button', language)}
          </button>
        </div>
      </form>

      {/* Example word chips */}
      {!result && !loading && (
        <div className={clsx('mb-8 flex flex-wrap gap-2 items-center', isRtl && 'flex-row-reverse')}>
          <span className={clsx('text-xs text-gray-400 font-medium shrink-0', isRtl && 'font-arabic')}>
            {t('vocab_try_examples', language)}
          </span>
          {EXAMPLE_WORDS.map((word) => (
            <button
              key={word}
              type="button"
              onClick={() => setQuery(word)}
              className="px-3 py-1 text-sm font-arabic bg-gray-100 hover:bg-teal-50 hover:text-teal-700 border border-gray-200 hover:border-teal-300 rounded-full transition-colors"
              dir="rtl"
            >
              {word}
            </button>
          ))}
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 p-4 mb-6">
          <p className={clsx('text-red-700 text-sm', isRtl && 'text-right font-arabic')}>{error}</p>
        </div>
      )}

      {/* Result: found */}
      {result && result.status === 'found' && (
        <WordResultCard result={result} language={language} isRtl={isRtl} />
      )}

      {/* Result: safe-refusal state */}
      {result && result.status === 'no_verified_source' && (
        <SafeRefusalCard result={result} language={language} isRtl={isRtl} />
      )}

      {/* Default state — planned sources catalogue */}
      {!result && !error && !loading && (
        <PlannedSourcesCatalogue language={language} isRtl={isRtl} />
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Word result card — shown when status === 'found'
// ---------------------------------------------------------------------------

interface CardProps {
  language: 'ar' | 'en';
  isRtl: boolean;
}

interface WordResultCardProps extends CardProps {
  result: VocabularyResponse;
}

function WordResultCard({ result, language, isRtl }: WordResultCardProps) {
  return (
    <div className="space-y-4">
      {/* Main card */}
      <div className="rounded-xl border border-teal-200 bg-white p-5 shadow-sm">

        {/* Word + status */}
        <div className={clsx('flex items-start gap-3 mb-4', isRtl && 'flex-row-reverse')}>
          <CheckCircle className="w-5 h-5 text-teal-600 mt-0.5 shrink-0" />
          <div className="flex-1 min-w-0">
            <h2 className="flex items-center gap-2 flex-wrap">
              <span dir="rtl" className="font-arabic text-2xl font-bold text-gray-900">
                {result.word}
              </span>
              <span className="inline-flex items-center gap-1 text-xs font-medium text-teal-700 bg-teal-50 border border-teal-200 rounded-full px-2.5 py-0.5">
                <CheckCircle className="w-3 h-3" />
                {language === 'ar' ? 'تم التحقق' : 'Verified source'}
              </span>
            </h2>
          </div>
        </div>

        {/* Morphology chips */}
        {(result.root || result.pattern || result.pos_tag) && (
          <div className={clsx('flex flex-wrap gap-2 mb-4', isRtl && 'flex-row-reverse')}>
            {result.root && (
              <div className="flex flex-col items-center bg-teal-50 border border-teal-200 rounded-lg px-3 py-2">
                <span className={clsx('text-xs text-teal-500', isRtl && 'font-arabic')}>
                  {language === 'ar' ? 'الجذر' : 'Root'}
                </span>
                <span dir="rtl" className="font-arabic font-bold text-teal-800 text-base">
                  {result.root}
                </span>
              </div>
            )}
            {result.pattern && (
              <div className="flex flex-col items-center bg-indigo-50 border border-indigo-100 rounded-lg px-3 py-2">
                <span className={clsx('text-xs text-indigo-400', isRtl && 'font-arabic')}>
                  {language === 'ar' ? 'الوزن' : 'Pattern'}
                </span>
                <span dir="rtl" className="font-arabic font-bold text-indigo-700 text-base">
                  {result.pattern}
                </span>
              </div>
            )}
            {result.pos_tag && (
              <div className="flex flex-col items-center bg-amber-50 border border-amber-100 rounded-lg px-3 py-2">
                <span className={clsx('text-xs text-amber-500', isRtl && 'font-arabic')}>
                  {language === 'ar' ? 'نوع الكلمة' : 'Part of Speech'}
                </span>
                <span dir="rtl" className="font-arabic font-bold text-amber-800 text-base">
                  {result.pos_tag}
                </span>
              </div>
            )}
          </div>
        )}

        {/* English meaning */}
        {result.meaning_en && (
          <div className="mb-3">
            <p className="text-xs text-gray-400 uppercase tracking-wide mb-1" dir="ltr">
              {language === 'ar' ? 'المعنى بالإنجليزية' : 'English Meaning'}
            </p>
            <p dir="ltr" className="text-gray-800 text-base font-medium">
              {result.meaning_en}
            </p>
          </div>
        )}

        {/* Arabic meaning */}
        {result.meaning_ar && (
          <div className="mb-3">
            <p className="text-xs text-gray-400 uppercase tracking-wide mb-1" dir="ltr">
              {language === 'ar' ? 'المعنى العربي' : 'Arabic Meaning'}
            </p>
            <p dir="rtl" className="font-arabic text-gray-800 text-base font-medium text-right">
              {result.meaning_ar}
            </p>
          </div>
        )}

        {/* Example verses */}
        {result.example_verses && result.example_verses.length > 0 && (
          <div className="mb-3">
            <p className="text-xs text-gray-400 uppercase tracking-wide mb-1" dir="ltr">
              {language === 'ar' ? 'آيات' : 'Verse'}
            </p>
            <div className={clsx('flex flex-wrap gap-1.5', isRtl && 'flex-row-reverse')}>
              {result.example_verses.map((ref) => (
                <span
                  key={ref}
                  className="inline-flex items-center text-xs font-mono bg-gray-100 text-gray-600 border border-gray-200 rounded px-2 py-0.5"
                  dir="ltr"
                >
                  {ref}
                </span>
              ))}
            </div>
          </div>
        )}

        {/* Source attribution */}
        <div className="pt-3 border-t border-gray-100">
          <div className={clsx('flex items-center gap-1.5 text-xs text-gray-400', isRtl && 'flex-row-reverse')}>
            <BookOpen className="w-3.5 h-3.5 shrink-0" />
            <span dir="ltr">
              {result.source_title_en || result.source_id || 'Quranic Arabic Corpus'}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

